<?php use Hls\Http\View as V; $e=fn($v)=>V::escape($v);$url=$this->url('/maintenance/p2h');$hidden=fn($a)=>array_map(fn($k,$v)=>'<input type="hidden" name="'.$e($k).'" value="'.$e($v).'">',array_keys($a),array_values($a)); ?>
<?php if($mode==='list'): ?><div class="master-toolbar"><?php if($access->can('equipment.p2h.create')): ?><a class="button primary" href="<?= $e($url.'?mode=create') ?>">Buat P2H</a><?php endif ?></div><?php ob_start();foreach($rows as $r): ?><tr><td><?= $e($r['official_number']??$r['internal_ref']) ?></td><td><?= $e($r['asset_code'].' — '.$r['asset_name']) ?></td><td><?= $e($r['inspected_at']) ?></td><td><?= $e($r['status']) ?></td><td><?= $e($r['fitness_status']??'Belum direview') ?></td><td><a href="<?= $e($url.'?mode=detail&id='.$r['id']) ?>">Detail</a></td></tr><?php endforeach;echo $this->component('table',['caption'=>'Data P2H','headers'=>['Nomor','Unit','Tanggal','Status','Kelayakan','Aksi'],'rowsHtml'=>ob_get_clean(),'hasRows'=>(bool)$rows,'emptyHeading'=>'Belum ada inspeksi','emptyMessage'=>'Belum ada P2H dalam cakupan Anda.']); ?>
<?php elseif($mode==='create'): ?><form class="panel master-form" method="post" action="<?= $e($url) ?>"><?= $this->csrf() ?><?= implode('', $hidden(['action'=>'save','branch_id'=>$_POST['branch_id']??'','request_key'=>bin2hex(random_bytes(32))])) ?><label>Cabang <input name="branch_id" type="number" required></label><label>Unit <select name="asset_id" required><?php foreach($assets as $a): ?><option value="<?= (int)$a['id'] ?>"><?= $e($a['code'].' — '.$a['name']) ?></option><?php endforeach ?></select></label><label>Waktu Pemeriksaan <input name="inspected_at" type="datetime-local" required></label><label>Shift <input name="shift"></label><label>Lokasi <input name="location"></label><label>Satuan Meter <select name="meter_type"><option>HM</option><option>KM</option></select></label><label>HM/KM <input name="meter_reading" type="number" min="0" step="0.001"></label><label>Catatan Umum <textarea name="general_note"></textarea></label><h2>Checklist</h2><?php foreach([['engine','Mesin','Oli mesin'],['hydraulic','Hidrolik','Selang hidrolik'],['structure','Struktur','Attachment'],['safety','Keselamatan','Lampu dan klakson']] as [$cat,$label,$item]): ?><fieldset><legend><?= $e($label) ?></legend><input type="hidden" name="items[<?= $e($cat) ?>][category]" value="<?= $e($label) ?>"><input type="hidden" name="items[<?= $e($cat) ?>][label]" value="<?= $e($item) ?>"><label>Hasil <select name="items[<?= $e($cat) ?>][result]"><option>BAIK</option><option>RUSAK</option><option>TIDAK_BERLAKU</option></select></label><label>Severity <select name="items[<?= $e($cat) ?>][severity]"><option value="">—</option><option>MINOR</option><option>MAJOR</option><option>CRITICAL</option></select></label><label>Catatan <textarea name="items[<?= $e($cat) ?>][note]"></textarea></label></fieldset><?php endforeach ?><button class="primary">Simpan P2H DRAFT</button></form>
<?php else: ?><section class="panel"><dl class="detail-grid"><dt>Nomor</dt><dd><?= $e($row['official_number']??$row['internal_ref']) ?></dd><dt>Unit</dt><dd><?= $e($row['asset_code'].' — '.$row['asset_name']) ?></dd><dt>Status</dt><dd><?= $e($row['status']) ?></dd><dt>Kelayakan</dt><dd><?= $e($row['fitness_status']??'Belum direview') ?></dd><dt>Catatan</dt><dd><?= $e($row['general_note']) ?></dd></dl></section><?php if($row["status"]==="REVIEWED"&&$row["fitness_status"]==="HOLD"&&$access->can("maintenance.wo.create")): ?><p><a class="button primary" href="/maintenance/work-orders?new=1&source_p2h_id=<?= (int)$row["id"] ?>&asset_id=<?= (int)$row["asset_id"] ?>">Buat Work Order</a></p><?php endif ?><?php if(!empty($holds)): ?><section class="panel"><h2>Riwayat HOLD</h2><?php foreach($holds as $h): ?><p><strong><?= $e($h["released_at"]?"Selesai":"Aktif") ?></strong> � <?= $e($h["reason"]) ?> (<?= $e($h["activated_at"]) ?>)<?php if(!$h["released_at"]&&$access->can("equipment.p2h.hold.release")): ?><form method="post" action="/maintenance/p2h-release" class="stack-form"><?= $this->csrf() ?><input type="hidden" name="hold_id" value="<?= (int)$h["id"] ?>"><input type="hidden" name="branch_id" value="<?= (int)$row["branch_id"] ?>"><input type="text" name="release_reason" required maxlength="2000" placeholder="Alasan release"><button type="submit">Release HOLD</button></form><?php endif ?></p><?php endforeach ?></section><?php endif ?><?php ob_start();foreach($items as $i): ?><tr><td><?= $e($i['category']) ?></td><td><?= $e($i['item_label']) ?></td><td><?= $e($i['result']) ?></td><td><?= $e($i['severity']??'—') ?></td><td><?= $e($i['note']) ?></td></tr><?php endforeach;echo $this->component('table',['caption'=>'Checklist','headers'=>['Kategori','Item','Hasil','Severity','Catatan'],'rowsHtml'=>ob_get_clean(),'hasRows'=>true]); ?><?php if($row['status']==='DRAFT'&&$access->can('equipment.p2h.submit')): ?><form method="post" action="<?= $e($url) ?>"><?= $this->csrf() ?><?= implode('', $hidden(['action'=>'submit','id'=>$row['id'],'branch_id'=>$row['branch_id'],'request_key'=>bin2hex(random_bytes(32))])) ?><button>Kirim untuk Review</button></form><?php elseif($row['status']==='SUBMITTED'&&$access->can('equipment.p2h.review')): ?><form method="post" action="<?= $e($url) ?>"><?= $this->csrf() ?><?= implode('', $hidden(['action'=>'review','id'=>$row['id'],'branch_id'=>$row['branch_id'],'request_key'=>bin2hex(random_bytes(32))])) ?><label>Hasil <select name="fitness_status"><option>FIT_FOR_OPERATION</option><option>FIT_WITH_NOTES</option><option>HOLD</option></select></label><button>Review P2H</button></form><?php endif ?><p><a href="<?= $e($url.'?mode=print&id='.$row['id']) ?>">Tampilan Cetak</a></p><?php endif ?>
